const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={lang:'es',style:'immersive'};
const directionText={essential:{title:['01 / Esencial','01 / Essential'],copy:['Claridad desde el primer momento. Arquitectura, información y decisiones en una estructura directa.','Clarity from the first moment. Architecture, information and decisions in a direct structure.']},editorial:{title:['02 / Editorial','02 / Editorial'],copy:['Una nueva mirada a la ciudad. Composiciones a medida y una historia propia para cada proyecto.','A fresh perspective on the city. Bespoke compositions and an individual story for each project.']},immersive:{title:['03 / Inmersivo','03 / Immersive'],copy:['Arquitectura que se descubre. Una entrada cinematográfica, con acceso directo a lo que necesitas saber.','Architecture to discover. A cinematic entrance with direct access to everything you need to know.']}};
const headlines={home:{essential:['Espacios para<br>tu próxima<br><em>etapa.</em>','Spaces for<br>your next<br><em>chapter.</em>'],editorial:['Una ciudad.<br>Otra forma<br>de <em>vivirla.</em>','One city.<br>A new way<br>to <em>live.</em>'],immersive:['El próximo<br>capítulo<br>de <em>Quito.</em>','Quito’s<br>next<br><em>chapter.</em>']},project:{essential:['Tu espacio.<br>Tu forma<br>de <em>vivir.</em>','Your space.<br>Your way<br>to <em>live.</em>'],editorial:['La vida<br>tiene otro<br><em>color.</em>','Life in<br>a different<br><em>colour.</em>'],immersive:['Imagina<br>llegar<br>a <em>casa.</em>','Imagine<br>coming<br><em>home.</em>']}};
function render(){document.body.classList.remove('essential','editorial','immersive');document.body.classList.add(state.style);document.documentElement.lang=state.lang==='es'?'es-EC':'en';$$('[data-es][data-en]').forEach(el=>el.innerHTML=el.dataset[state.lang]);$$('[data-style]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.style===state.style));$$('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===state.lang));const i=state.lang==='es'?0:1;$$('[data-headline]').forEach(el=>el.innerHTML=headlines[el.dataset.headline][state.style][i]);if($('#direction-title')){$('#direction-title').textContent=directionText[state.style].title[i];$('#direction-copy').textContent=directionText[state.style].copy[i];}$$('.brand-logo').forEach(im=>im.src='/assets/alpha-logo-'+'white'+'.webp');$$('a[href^="/"]').forEach(el=>{const u=new URL(el.href);u.searchParams.set('style',el.dataset.previewStyle||state.style);u.searchParams.set('lang',state.lang);el.href=u.pathname+u.search+u.hash});if(typeof updateJourneyText==='function')updateJourneyText();const u=new URL(location.href);u.searchParams.set('style',state.style);u.searchParams.set('lang',state.lang);history.replaceState(null,'',u);document.dispatchEvent(new CustomEvent('site:render'));}
const params=new URLSearchParams(location.search);if(['essential','editorial','immersive'].includes(params.get('style')))state.style=params.get('style');if(params.get('lang')==='en')state.lang='en';
$$('[data-style]').forEach(b=>b.addEventListener('click',()=>{state.style=b.dataset.style;render()}));$$('[data-lang]').forEach(b=>b.addEventListener('click',()=>{state.lang=b.dataset.lang;render()}));$$('[data-open]').forEach(b=>b.addEventListener('click',()=>{const d=document.getElementById(b.dataset.open);d.showModal();if(d.id==='tour'&&typeof startJourney==='function')startJourney()}));$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$$('[data-choose]').forEach(b=>b.addEventListener('click',()=>{state.style=b.dataset.choose;render();b.closest('dialog').close();window.scrollTo({top:0,behavior:'smooth'})}));
const scenes=[{image:'pixel-exterior-render',kicker:['01 / LLEGAR','01 / ARRIVE'],title:['Tu primera mirada.','Your first impression.'],description:['Pixel, en La Magdalena. La visita comienza desde afuera.','Pixel, in La Magdalena. Your visit begins outside.'],alt:['Render de la fachada de Pixel','Render of the Pixel exterior']},{image:'pixel-lobby-render',kicker:['02 / ENTRAR','02 / STEP INSIDE'],title:['Bienvenido a Pixel.','Welcome to Pixel.'],description:['El lobby: el primer espacio que te recibe.','The lobby: the first space to welcome you.'],alt:['Render del lobby Pixel Colors','Render of the Pixel Colors lobby']},{image:'pixel-living-render',kicker:['03 / HABITAR','03 / COME HOME'],title:['Aquí comienza tu día.','Your day starts here.'],description:['Sala, comedor y cocina. Imagina tu vida en este espacio.','Living, dining and kitchen. Imagine your life in this space.'],alt:['Render del interior de un departamento Pixel','Render of a Pixel apartment interior']},{image:'pixel-pool-water-render',kicker:['04 / DISFRUTAR','04 / UNWIND'],title:['Un momento para ti.','A moment for yourself.'],description:['Pixel Pool. Explora los espacios que complementan tu hogar.','Pixel Pool. Discover the spaces that complement your home.'],alt:['Render de la piscina Pixel Pool','Render of the Pixel Pool swimming pool']}];
let journeyIndex=0,journeyBusy=false,journeyTimer=null,journeyEndTimer=null;
function updateJourneyText(){if(!$('#tour'))return;const s=scenes[journeyIndex],i=state.lang==='es'?0:1;$('#scene-kicker').textContent=s.kicker[i];$('#scene-title').textContent=s.title[i];$('#scene-description').textContent=s.description[i];$('#tour-image').alt=s.alt[i];$('#journey-counter').textContent=String(journeyIndex+1).padStart(2,'0');$('#journey-prev').disabled=journeyIndex===0;$('#journey-next').textContent=journeyIndex===3?(i===0?'Volver al inicio':'Back to start'):(i===0?'Continuar':'Continue');$$('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.scene)===journeyIndex));}
function startJourney(){clearTimeout(journeyTimer);clearTimeout(journeyEndTimer);journeyBusy=false;journeyIndex=0;$('#tour-image').src='/assets/'+scenes[0].image+'.png';$('#tour-stage').className='tour-stage open arrival';updateJourneyText();}
function goScene(next){if(journeyBusy||next===journeyIndex)return;const stage=$('#tour-stage');const elevator=journeyIndex===1&&next===2;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;journeyBusy=true;stage.classList.remove('arrival');stage.classList.toggle('elevator',elevator);stage.classList.toggle('fading',!elevator);stage.classList.remove('open');journeyTimer=setTimeout(()=>{journeyIndex=next;$('#tour-image').src='/assets/'+scenes[next].image+'.png';stage.classList.toggle('arrival',next===0);updateJourneyText();journeyEndTimer=setTimeout(()=>{stage.classList.remove('fading');stage.classList.add('open');journeyBusy=false;},reduce?0:elevator?450:80);},reduce?0:elevator?900:350);}
if($('#tour')){$$('[data-scene]').forEach(b=>b.addEventListener('click',()=>goScene(Number(b.dataset.scene))));$('#journey-prev').addEventListener('click',()=>goScene(Math.max(0,journeyIndex-1)));$('#journey-next').addEventListener('click',()=>goScene((journeyIndex+1)%scenes.length));$('#tour-to-details').addEventListener('click',()=>{$('#tour').close();$('#details').scrollIntoView({behavior:'smooth'});history.replaceState(null,'',location.pathname+location.search+'#details')});$('#tour').addEventListener('close',()=>{clearTimeout(journeyTimer);clearTimeout(journeyEndTimer);journeyBusy=false});}
render();
